      document.documentElement.classList.add(CLASS_NAME_OPEN)
    }
  }"},{"path":"js/src/dialog-base.ts","sha256":"365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b","before":"  protected _closeAndCleanup(): void {
    this._element.close()
    this._openedAsModal = false

    // Only restore scroll if no other modal dialogs are open
    if (!document.querySelector('dialog[open]:modal')) {
      document.documentElement.classList.remove(CLASS_NAME_OPEN)
    }
  }","after":"  protected _closeAndCleanup(): void {
    this._element.close()
    this._openedAsModal = false

    // Only restore scroll if no other modal dialogs are open
    if (!document.querySelector('dialog[open]:modal')) {
      document.documentElement.classList.remove(CLASS_NAME_OPEN)
    }

    // Restore focus to the element that opened the dialog
    if (this._relatedTarget && isVisible(this._relatedTarget)) {
      this._relatedTarget.focus({ preventScroll: true })
    }
    this._relatedTarget = null
  }"},{"path":"js/src/dialog-base.ts","sha256":"365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b","before":"  protected _onCancel(): void {
    // No-op by default — Dialog overrides to fire cancel event
  }","after":"  protected _onCancel(): void {
    // No-op by default — Dialog overrides to fire cancel event
  }

  protected _enforceFocus(): void {
    // Focus the first focusable element, preferring [autofocus]
    const autofocus = this._element.querySelector('[autofocus]') as HTMLElement | null
    if (autofocus) {
      autofocus.focus({ preventScroll: true })
      return
    }
    const focusable = this._element.querySelector('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])') as HTMLElement | null
    if (focusable) {
      focusable.focus({ preventScroll: true })
    }
  }"},{"path":"js/src/dialog-base.ts","sha256":"365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b","before":"import BaseComponent from './base-component.js'
